```dart
class _NewsListPageState extends State<NewsListPage> with SingleTickerProviderStateMixin {
  static final _tween = Tween<double>(begin: 0.25, end: 1);

  List<NewsModel> _newsItems = [];

  late final AnimationController _scaleController;
  late final Animation<double> _scaleAnimation;

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _scaleController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _scaleController = AnimationController(
      vsync: this,
      duration: Duration(milliseconds: 200),
    );
    _scaleAnimation = _tween.animate(_scaleController);
  }

  void _initData() {
    final newsRepository = context.read<NewsRepository>();

    // Показываем кэш мгновенно, сеть работает в фоне
    newsRepository.loadCachedNewsFeed(
      onLoaded: (cached) {
        if (mounted && cached.isNotEmpty) {
          setState(() => _newsItems = cached);
        }
      },
      onRefreshed: () {
        // После обновления из сети запускаем анимацию и обновляем UI
        if (!mounted) return;
        _scaleController.forward();
        newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: false)).then((fresh) {
          if (mounted) {
            setState(() => _newsItems = fresh);
          }
        });
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.news)),
      body: ScaleTransition(
        scale: _scaleAnimation,
        child: ListView.builder(
          itemCount: _newsItems.length,
          itemBuilder: (BuildContext context, int index) {
            final NewsModel news = _newsItems[index];

            return Padding(
              key: ValueKey(news.link),
              padding: index == 0 ? EdgeInsets.zero : const EdgeInsets.only(top: 16),
              child: NewsCard(model: news),
            );
          },
          padding: const EdgeInsets.fromLTRB(22, 16, 22, 40),
        ),
      ),
    );
  }
}
```

Wait, there's an issue with my `onRefreshed` callback in the repository. It gets called after network fetch completes and cache is saved. But then I'm calling `loadNewsFeed(forceRefresh: false)` to read from cache again - this adds unnecessary complexity. 

Simpler approach: The repository should also return fresh data in onRefreshed callback, or we just re-read from DB (which is fast).

Actually, let me reconsider the repository implementation. When `onRefreshed` fires, the data is already saved to cache. So reading it back is fine - it's a local DB operation and very fast. But actually I can make this cleaner by having the repo pass fresh data to onRefreshed:

```dart
void loadCachedNewsFeed(
  void Function(List<NewsModel>) onLoaded, {
  void Function(List<NewsModel>)? onRefreshed,
}) {
  final dbFuture = _dbDatasource.getNewsList();
  dbFuture.then(onLoaded);

  _fetchAndCache().then((fresh) {
    if (onRefreshed != null && fresh.isNotEmpty) onRefreshed(fresh);
  });
}

Future<List<NewsModel>> _fetchAndCache() async {
  try {
    final List<NewsModel> fresh = await _restDatasource.getNewsList();
    await _dbDatasource.saveNewsList(fresh);
    return fresh;
  } catch (_) {
    return const <NewsModel>[];
  }
}
```

This is cleaner - onRefreshed gets the actual fresh data, no need to re-read from DB.

